#[test]
fn quaternion_curve_uses_normalized_shortest_path() {
    let keys = vec![
        TimelinePropertyKey {
            tick: TimelineTick::ZERO,
            value: TimelinePropertyValue::Quat([0.0, 0.0, 0.0, 1.0]),
        },
        TimelinePropertyKey {
            tick: TimelineTick::new(10),
            value: TimelinePropertyValue::Quat([0.0, 0.0, 0.0, -1.0]),
        },
    ];
    let Some(TimelinePropertyValue::Quat(value)) =
        sample_timeline_property(&keys, TimelineTick::new(5))
    else {
        panic!("expected quaternion sample");
    };
    let length_squared = value.iter().map(|component| component * component).sum::<f64>();
    assert!((length_squared - 1.0).abs() < 1.0e-12);
    assert_eq!(value, [0.0, 0.0, 0.0, 1.0]);
}

#[test]
fn invalid_property_key_order_and_type_are_diagnostics() {
    let mut doc = TimelineDocument::new("curve", TimelineTick::new(100));
    doc.tracks.push(TimelineTrack {
        id: TimelineTrackId::generate(),
        name: "curve".into(),
        kind: TimelineTrackKind::TransformProperty,
        enabled: true,
        priority: 0,
        binding: Some(TimelineBinding::Entity {
            entity: EntityId::generate(),
        }),
        clips: vec![clip(TimelineClipPayload::TransformProperty {
            property: "engine.transform.translation".into(),
            keys: vec![
                TimelinePropertyKey {
                    tick: TimelineTick::new(5),
                    value: TimelinePropertyValue::Vec3([0.0, 0.0, 0.0]),
                },
                TimelinePropertyKey {
                    tick: TimelineTick::new(5),
                    value: TimelinePropertyValue::Number(1.0),
                },
            ],
        })],
    });
    let diagnostics = validate_timeline(&doc);
    assert!(diagnostics
        .iter()
        .any(|diagnostic| diagnostic.code == "timeline.property.key_order"));
    assert!(diagnostics
        .iter()
        .any(|diagnostic| diagnostic.code == "timeline.property.type_mismatch"));
}

#[test]
fn blend_must_fit_inside_clip_duration() {
    let mut bad_clip = clip(TimelineClipPayload::Event {
        name: "sequence.started".into(),
        payload: String::new(),
    });
    bad_clip.blend = TimelineBlend {
        in_ticks: TimelineTick::new(8),
        out_ticks: TimelineTick::new(8),
    };
    let mut doc = TimelineDocument::new("blend", TimelineTick::new(100));
    doc.tracks.push(TimelineTrack {
        id: TimelineTrackId::generate(),
        name: "events".into(),
        kind: TimelineTrackKind::Event,
        enabled: true,
        priority: 0,
        binding: None,
        clips: vec![bad_clip],
    });
    assert!(validate_timeline(&doc)
        .iter()
        .any(|diagnostic| diagnostic.code == "timeline.clip.blend"));
}

#[test]
fn compiled_clip_retains_track_priority_and_blend() {
    let mut camera_clip = clip(TimelineClipPayload::CameraCut);
    camera_clip.blend = TimelineBlend {
        in_ticks: TimelineTick::new(2),
        out_ticks: TimelineTick::new(3),
    };
    let mut doc = TimelineDocument::new("camera", TimelineTick::new(100));
    doc.tracks.push(TimelineTrack {
        id: TimelineTrackId::generate(),
        name: "camera".into(),
        kind: TimelineTrackKind::CameraCut,
        enabled: true,
        priority: 17,
        binding: Some(TimelineBinding::Entity {
            entity: EntityId::generate(),
        }),
        clips: vec![camera_clip],
    });
    let compiled = doc.compile().schedule.expect("valid schedule");
    let CompiledTimelinePayload::Clip {
        track_priority,
        blend,
        ..
    } = compiled.entries()[0].payload()
    else {
        panic!("expected compiled clip");
    };
    assert_eq!(*track_priority, 17);
    assert_eq!(*blend, TimelineBlend {
        in_ticks: TimelineTick::new(2),
        out_ticks: TimelineTick::new(3),
    });
}

